const m = $input.first().json;
const l2b = m.leads_received ? ((m.bookings_created / m.leads_received) * 100).toFixed(1) : 'N/A';
const b2c = m.bookings_created ? ((m.jobs_completed / m.bookings_created) * 100).toFixed(1) : 'N/A';
const body = `LOCALFLOW WEEKLY OPERATIONS

LEADS
Received: ${m.leads_received}
Qualified: ${m.leads_qualified}
Outside area: ${m.outside_area}
Duplicates: ${m.duplicates}

CONVERSION
Lead → Booking: ${l2b}%
Booking → Completed: ${b2c}%

OPERATIONS
Bookings: ${m.bookings_created}
Completed jobs: ${m.jobs_completed}
Follow-ups sent: ${m.follow_ups_sent}

CUSTOMER EXPERIENCE
Review requests: ${m.review_requests}
Unsatisfied: ${m.unsatisfied}

AUTOMATION
Runs: ${m.workflow_runs}
Failed: ${m.workflow_failed}
`;
return [{ json: { ...m, report_body: body, lead_to_booking_rate: l2b, booking_to_completion_rate: b2c } }];
